from typing import List, Optional

from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.test_cases.csv4all_test import CSV4AllTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import IterationFailedError, TestExecutionFailed, \
    RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.test_cases.upgrade_rollback_test import UpgradeRollbackTest
from taf.rfrl.csv4all.resources.utilities.decorators import wrapper_decorator, method_decorator
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class RollbackTest(UpgradeRollbackTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 use_dcap: Optional[bool] = False, customers_list: Optional[list] = None,
                 sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: Optional[bool] = False,
                 package_suffix: Optional[str] = "A54", rollback_reverse_order: bool = False,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details=nodes_details, test_nodes_details=test_nodes_details,
                         iterations_per_node=iterations_per_node, report=False, calculate_kpi=False, use_dcap=use_dcap,
                         customers_list=customers_list, sw_build=sw_build, topology=topology,
                         stop_test_after_fail=stop_test_after_fail, package_suffix=package_suffix,
                         restore_to_target_sw=False, rollback_reverse_order=rollback_reverse_order,
                         detailed_console_log=detailed_console_log, collect_passed_logs=collect_passed_logs)
        self.l3_call_result = None
        self.switch_paths = False
        self.rollback_source_sw = None

    def test_setup(self):
        CSV4AllTest.test_setup(self)

    def test_operation(self, node):
        self.software_rollback_test()
        self.switch_paths = True
        return self.failed_nodes

    @method_decorator()
    def sw_rollback_operation(self, node):
        node.logsverify.reset_check = False
        operation = "rollback"
        test_logger(f"{self.current_iteration} - source sw: {node.source_sw}, target sw: {node.target_sw}")
        try:
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.gather_blackbox_and_set_reset_counter(operation)
            self.add_all_allowed_specific_faults(node)
            self.switch_source_sw(node)
            node.perform_rollback_and_wait_for_reload()
            test_logger(f"verify BTS state after sw rollback")
            self.failed_nodes_during_rollback = self.verify_nodes_after_sw_change_operation(node, operation)
            return self.failed_nodes_during_rollback
        except Exception as e:
            self.switch_source_sw(node, default_value=True)
            self.failed_nodes_during_rollback = {node.node_alias}
            node.btsverify.bts_fault_message += f"\n{str(e)}"
            self.exception_handling(operation, e)
            return self.failed_nodes_during_rollback
        finally:
            self.switch_source_sw(node, default_value=True)
            self.remove_allowed_alarms_from_nodes(self.nodes, self.all_allowed_specific_faults)
            node.logsverify.reset_check = True

    def switch_source_sw(self, node, default_value=False):
        if default_value:
            if self.rollback_source_sw:
                node.source_sw = self.rollback_source_sw
                self.rollback_source_sw = None
        else:
            self.rollback_source_sw = node.source_sw
            node.source_sw = node.target_sw

    @staticmethod
    def swap_initial_and_target_sw(node):
        new_target = node.source_sw
        node.source_sw = node.target_sw
        node.target_sw = new_target

    @wrapper_decorator
    def _precondition(self, node):
        self._set_current_logs_dir(node)
        active_sw = node.get_active_sw()
        if node.source_sw != active_sw:
            raise FatalError(f"Expected software on BTS is different than requested\n"
                             f"Current software: {active_sw}\n"
                             f"Expected software: {node.source_sw}")

    @method_decorator()
    def check_nodes_state_before_rollback(self, node, operation: str = "rollback"):
        try:
            node.verify_active_sw_version(node.source_sw + node.testpackage_prefix())
        except WrongSwVersion:
            return False
        return super().check_nodes_state_before_operation(node, operation)

    def test(self):
        for node in self.test_nodes:
            if self.switch_paths:
                self.swap_initial_and_target_sw(node)
            node.target_sw_path = f"{node.target_sw}_release_BTSSM_downloadable_{self.package_suffix}"
        self.run_iteration_precondition()
        self.failed_nodes = self.test_operation(None)
        self.verify_failed_nodes_after_iteration()
        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    def run_test(self):
        try:
            self.run_setup()
            self.execute_test_in_loop()
            if any(nodes_results != "passed" for nodes_results in self.test_results.values()):
                self.recovery_bts_after_fail()
                raise TestExecutionFailed("Rollback test failed but further execution will be continued")
        except (RecoveryAttemptFailedError, WrongSwVersion):
            raise FatalError("Recovery of failed nodes fails! Further Execution will be aborted!")
        finally:
            if self.report_to_rp:
                self.report_results()
            self.run_teardown()

